# bench-control-ct-round2-select: private CPU kernel (internet on). Cascaded Tanks round 2: pre-registered SELECTION on the ESTIMATION record only.
# AUTO-GENERATED by kernels/ct_round2_select/make_kernel.py from kernel_main.py + the payload (do not edit script.py).
#
# Stages (each logged; the test record's values are never read: ct2/select2.py patches the loader to return (train, None) and test_eval to raise):
#   1 payload   extract the byte-identical committed sources, verify every sha256 against the embedded manifest
#   2 venv      Python 3.12 venv in /tmp with the SAME package versions as round 1 (uv)
#   3 git       throw-away repo; git tree hashes of ct/ (must be the round-1 tree) and ct2/ and the blob of the pre-registration must match
#   4 data      Google Drive loader URL; zip and .mat sha256 must match; no fallback
#   5 preflight fit-free checks and 2-iteration plumbing (selftest.py), then the whole driver once with 0.5 % of the iteration counts on S00,S01,S13
#   6 select    ct2/select2.py: stage 1 (14 candidates x 5 jobs), rule 1, stage 2 (3 fit variants), rule 2, dry run on TRAIN; 4 single-thread workers
import base64, glob, hashlib, io, json, os, platform, re, shutil, subprocess, sys, tarfile, time, traceback

T0 = time.time()
OUT = "/kaggle/working/out"
ROOT = "/tmp/ctrepo"
VENV = "/tmp/ctvenv"
PY = VENV + "/bin/python"
KERNEL = "sankalpsthakur/bench-control-ct-round2-select"
PREREG = "PREREGISTRATION-CT-ROUND2.md"
PINS = ["numpy==2.5.3", "scipy==1.18.1", "jax==0.11.2", "jaxlib==0.11.2", "nonlinear-benchmarks==1.0.1",
        "matplotlib<3.11", "progressbar==2.5", "rarfile==4.5", "tqdm==4.70.1", "requests==2.34.2"]
EXPECT_VERSIONS = {"numpy": "2.5.3", "scipy": "1.18.1", "jax": "0.11.2", "jaxlib": "0.11.2", "nonlinear_benchmarks": "1.0.1"}
WORKERS, DEADLINE_MIN = 4, 100

PAYLOAD_B64 = "__PAYLOAD_B64__"
EXPECT = json.loads(r'''__EXPECT_JSON__''')

ENV = dict(os.environ, OMP_NUM_THREADS="1", MKL_NUM_THREADS="1", OPENBLAS_NUM_THREADS="1", VECLIB_MAXIMUM_THREADS="1",
           XLA_FLAGS="--xla_cpu_multi_thread_eigen=false intra_op_parallelism_threads=1",
           JAX_COMPILATION_CACHE_DIR="/tmp/jaxcache", JAX_PERSISTENT_CACHE_MIN_COMPILE_TIME_SECS="0",
           PYTHONDONTWRITEBYTECODE="1", PYTHONUNBUFFERED="1")

os.makedirs(OUT + "/stages", exist_ok=True)
STATUS = {}


class Abort(Exception):
    pass


def log(*a):
    print(f"[{time.time() - T0:7.1f}s]", *a, flush=True)


def status(stage, **kw):
    STATUS[stage] = dict(t=round(time.time() - T0, 1), **kw)
    json.dump(STATUS, open(OUT + "/stage_status.json", "w"), indent=1)


def sh(cmd, name, env=None, cwd=None, check=True):
    log("$", " ".join(cmd))
    buf = []
    with open(f"{OUT}/stages/{name}.log", "a") as lf:
        p = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, env=env or ENV, cwd=cwd, bufsize=1)
        for line in p.stdout:
            print(line, end="", flush=True)
            lf.write(line)
            buf.append(line)
        rc = p.wait()
    if check and rc != 0:
        raise Abort(f"{name}: command failed with exit code {rc}")
    return rc, "".join(buf)


def sha256_file(path):
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(1 << 20), b""):
            h.update(chunk)
    return h.hexdigest()


def stage_banner():
    info = dict(utc_start=time.strftime("%Y-%m-%d %H:%M:%S", time.gmtime(T0)), python=sys.version, platform=platform.platform(),
                cpu_count=os.cpu_count(), kernel=KERNEL)
    try:
        info["cpu_model"] = [l.split(":", 1)[1].strip() for l in open("/proc/cpuinfo") if l.lower().startswith("model name")][0]
        info["mem_total_kb"] = [int(l.split()[1]) for l in open("/proc/meminfo") if l.startswith("MemTotal")][0]
    except Exception:
        pass
    json.dump(info, open(OUT + "/env.json", "w"), indent=1)
    log("ENV", json.dumps(info))
    log("EXPECT", json.dumps({k: v for k, v in EXPECT.items() if k != "manifest"}))


def stage_payload():
    if os.path.exists(ROOT):
        shutil.rmtree(ROOT)
    os.makedirs(ROOT)
    raw = base64.b64decode(PAYLOAD_B64)
    with tarfile.open(fileobj=io.BytesIO(raw), mode="r:gz") as tf:
        try:
            tf.extractall(ROOT, filter="data")
        except TypeError:
            tf.extractall(ROOT)
    bad = []
    for rel, want in EXPECT["manifest"].items():
        p = os.path.join(ROOT, rel)
        got = sha256_file(p) if os.path.exists(p) else "MISSING"
        if got != want:
            bad.append((rel, want, got))
    for d in ("ct", "ct2"):
        names = {os.path.basename(k) for k in EXPECT["manifest"] if k.startswith(d + "/")}
        for p in glob.glob(ROOT + f"/{d}/*"):
            if os.path.basename(p) not in names:
                bad.append((p, "not in manifest", "extra file"))
    for rel in EXPECT.get("executable", []):
        os.chmod(os.path.join(ROOT, rel), 0o755)
    os.makedirs(ROOT + "/runs", exist_ok=True)
    os.makedirs(ROOT + "/results", exist_ok=True)
    manifest_report = {rel: dict(sha256=sha256_file(os.path.join(ROOT, rel))) for rel in sorted(EXPECT["manifest"])}
    json.dump(manifest_report, open(OUT + "/manifest_verified.json", "w"), indent=1)
    for rel in sorted(EXPECT["manifest"]):
        log("SHA256", manifest_report[rel]["sha256"], rel)
    if bad:
        raise Abort("payload sha256 mismatch: " + json.dumps(bad))
    status("payload", ok=True, files=len(EXPECT["manifest"]))


def stage_venv():
    sh([sys.executable, "-m", "pip", "install", "-q", "uv"], "venv")
    uvbin = subprocess.check_output([sys.executable, "-c", "import uv; print(uv.find_uv_bin())"], text=True).strip()
    sh([uvbin, "venv", "--python", "3.12", VENV], "venv")
    sh([uvbin, "pip", "install", "--python", PY, *PINS], "venv")
    rc, txt = sh([uvbin, "pip", "freeze", "--python", PY], "venv")
    open(OUT + "/venv_freeze.txt", "w").write(txt)
    code = ("import sys, json, numpy, scipy, jax, jaxlib, matplotlib, nonlinear_benchmarks, importlib.metadata as m;"
            "print('VERSIONS', json.dumps(dict(python=sys.version.split()[0], numpy=numpy.__version__, scipy=scipy.__version__, jax=jax.__version__,"
            "jaxlib=jaxlib.__version__, matplotlib=matplotlib.__version__, nonlinear_benchmarks=m.version('nonlinear_benchmarks'))))")
    rc, txt = sh([PY, "-c", code], "venv")
    got = json.loads(txt.split("VERSIONS", 1)[1].strip().splitlines()[0])
    open(OUT + "/versions.json", "w").write(json.dumps(got, indent=1))
    wrong = {k: (v, got.get(k)) for k, v in EXPECT_VERSIONS.items() if got.get(k) != v}
    if wrong:
        raise Abort("package versions differ from round 1: " + json.dumps(wrong))
    status("venv", ok=True, versions=got)


def stage_git():
    g = ["git", "-c", "user.name=ct-kernel", "-c", "user.email=ct-kernel@localhost"]
    sh(["git", "init", "-q", "."], "git", cwd=ROOT)
    sh(g + ["add", ".gitignore", "ct", "ct2", PREREG], "git", cwd=ROOT)
    sh(g + ["commit", "-q", "-m", "committed sources, byte-identical to control repo " + EXPECT["repo_head"][:7]], "git", cwd=ROOT)
    got = {}
    for k, ref in (("git_tree_ct", "HEAD:ct"), ("git_tree_ct2", "HEAD:ct2"), ("git_blob_prereg", "HEAD:" + PREREG)):
        _, t = sh(["git", "rev-parse", ref], "git", cwd=ROOT)
        got[k] = t.strip()
        log("GIT", k, got[k], "expected", EXPECT[k])
    ok = all(got[k] == EXPECT[k] for k in got)
    status("git", ok=ok, **got)
    if not ok:
        raise Abort("git hashes of the committed sources differ from the control repo")


def stage_data():
    last = None
    for attempt in range(1, 4):
        shutil.rmtree(ROOT + "/data", ignore_errors=True)
        rc, txt = sh([PY, "tools/ct_data_check.py", EXPECT["data_zip_sha256"], EXPECT["data_mat_sha256"]], "data", cwd=ROOT, check=False)
        last = txt
        if rc == 0:
            line = [l for l in txt.splitlines() if l.startswith("DATA_CHECK ")][-1]
            status("data", ok=True, attempt=attempt, info=json.loads(line[len("DATA_CHECK "):]))
            return
        log(f"data attempt {attempt} failed (rc={rc}); retrying in 20 s")
        time.sleep(20)
    raise Abort("data check failed after 3 attempts; NOT falling back to any other copy. Last output tail: " + (last or "")[-800:])


def stage_preflight():
    sh([PY, "ct2/selftest.py", "equiv-C", "equiv-F1", "limits", "warm-S12", "job-S12:G0:fold1", "job-S01:G2:fold3", "job-S13:G0:level"], "preflight", cwd=ROOT)
    sh([PY, "ct2/select2.py", "--out", OUT + "/smoke", "--workers", str(WORKERS), "--maxiter-scale", "0.005", "--only", "S00,S01,S13"], "preflight", cwd=ROOT)
    shutil.rmtree(OUT + "/smoke", ignore_errors=True)
    status("preflight", ok=True)


def stage_select():
    status("select", started=True)
    rc, _ = sh([PY, "ct2/select2.py", "--out", OUT + "/select", "--workers", str(WORKERS), "--deadline-min", str(DEADLINE_MIN)], "select", cwd=ROOT, check=False)
    status("select", ok=(rc == 0), rc=rc)
    if rc != 0:
        raise Abort("select2.py exited with %s (partial results are in select/)" % rc)


def main():
    stage_banner()
    stage_payload()
    stage_venv()
    stage_git()
    stage_data()
    stage_preflight()
    stage_select()
    log("ALL STAGES DONE")


if __name__ == "__main__":
    rc = 0
    try:
        main()
    except Abort as e:
        log("ABORT:", e)
        status("abort", msg=str(e))
        rc = 2
    except Exception:
        log("CRASH:", traceback.format_exc())
        status("crash", tb=traceback.format_exc()[-800:])
        rc = 3
    shutil.rmtree(ROOT + "/data", ignore_errors=True)
    log("elapsed", round(time.time() - T0), "s")
    sys.exit(rc)
